import ctypes as C
from xml.sax.saxutils import escape
import os
class Id(C.Union):
    _fields_=[('number',C.c_int),('name',C.c_char_p),('phoneme',C.c_char*8)]
class Event(C.Structure):
    _fields_=[('type',C.c_int),('id',C.c_uint),('position',C.c_int),('length',C.c_int),('ms',C.c_int),('sample',C.c_int),('data',C.c_void_p),('u',Id)]
lib=C.CDLL('libespeak-ng.so.1')
fr=lib.espeak_Initialize(2,0,(os.environ['ESPEAK_DATA_PATH'].encode() if 'ESPEAK_DATA_PATH' in os.environ else None),0)
assert fr==22050,fr
assert lib.espeak_SetVoiceByName(b'ko')==0
assert lib.espeak_SetParameter(1,180,0)==0
lib.espeak_Info.restype=C.c_char_p
version=lib.espeak_Info(None).decode()
parts=[]; marks={}
@C.CFUNCTYPE(C.c_int,C.c_void_p,C.c_int,C.POINTER(Event))
def receive(wav,count,events):
    if wav and count: parts.append(C.string_at(wav,count*2))
    j=0
    while events[j].type:
        ev=events[j]
        if ev.type==3: marks[ev.u.name.decode()]=ev.ms
        j+=1
    return 0
lib.espeak_SetSynthCallback(receive)
def say(s,anchors):
    parts.clear(); marks.clear()
    buf=[]; last=0
    for pos,name in sorted(anchors):
        buf.extend((escape(s[last:pos]),f'<mark name="{name}"/><break time="1ms"/>'));last=pos
    text=('<speak>'+''.join(buf)+escape(s[last:])+'</speak>').encode()
    assert lib.espeak_Synth(text,len(text)+1,0,1,0,1|0x10|0x1000,None,None)==0
    return b''.join(parts),{k:v/1000 for k,v in marks.items()}
